'use strict';
const express = require('express');

const ALLOWED_TYPES = new Set(['image/jpeg', 'image/png', 'image/webp']);
const MAX_BYTES = 5 * 1024 * 1024;

function validFilename(name) {
  if (typeof name !== 'string' || name.length === 0) return false;
  if (name.includes('/') || name.includes('\\')) return false;
  return true;
}

function makeApp() {
  const app = express();
  app.use(express.json({ limit: '20mb' }));

  app.post('/api/uploads', (req, res) => {
    const { filename, content_type, size_bytes } = req.body || {};
    if (!validFilename(filename)) {
      return res.status(400).json({ error: 'invalid_filename' });
    }
    if (!ALLOWED_TYPES.has(content_type)) {
      return res.status(415).json({ error: 'unsupported_type' });
    }
    if (!Number.isFinite(size_bytes) || size_bytes > MAX_BYTES) {
      return res.status(413).json({ error: 'file_too_large' });
    }
    res.status(200).json({ stored: { filename, content_type, size_bytes } });
  });

  return app;
}

module.exports = { makeApp };

