npm install --silent --no-audit --no-fund && cat > tests/hidden.test.js <<'EOF'
const request = require('supertest');
const { makeApp } = require('../src/server');

const app = makeApp();

test('rejects unsupported type', async () => {
  const r = await request(app).post('/api/uploads').send({ filename: 'a.exe', content_type: 'application/octet-stream', size_bytes: 100 });
  expect(r.status).toBe(415);
  expect(r.body.error).toBe('unsupported_type');
});

test('rejects file > 5MB', async () => {
  const r = await request(app).post('/api/uploads').send({ filename: 'a.png', content_type: 'image/png', size_bytes: 6 * 1024 * 1024 });
  expect(r.status).toBe(413);
  expect(r.body.error).toBe('file_too_large');
});

test('rejects path traversal filename', async () => {
  const r = await request(app).post('/api/uploads').send({ filename: '../etc/passwd', content_type: 'image/png', size_bytes: 100 });
  expect(r.status).toBe(400);
  expect(r.body.error).toBe('invalid_filename');
});

test('accepts valid upload', async () => {
  const r = await request(app).post('/api/uploads').send({ filename: 'a.png', content_type: 'image/png', size_bytes: 1024 });
  expect(r.status).toBe(200);
});
EOF
